create table public.saved_projects(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,project_id)); create index saved_projects_user_id_idx on public.saved_projects(user_id); create index saved_projects_project_id_idx on public.saved_projects(project_id); create table public.business_claims(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,claimant_id uuid not null references public.profiles(id) on delete cascade,status public.claim_status not null default 'pending',verification_info jsonb not null default '{}'::jsonb,admin_notes text,reviewed_by uuid references public.profiles(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create trigger set_business_claims_updated_at before update on public.business_claims for each row execute function public.set_updated_at(); create index business_claims_business_id_idx on public.business_claims(business_id); create index business_claims_claimant_id_idx on public.business_claims(claimant_id); create index business_claims_status_idx on public.business_claims(status); alter table public.saved_projects enable row level security; alter table public.business_claims enable row level security; create policy "Homeowners manage their own saved projects" on public.saved_projects for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid())); create policy "Admins manage saved projects" on public.saved_projects for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "Claimants create their own claims" on public.business_claims for insert to authenticated with check(claimant_id=(select auth.uid())); create policy "Claimants view their own claims" on public.business_claims for select to authenticated using(claimant_id=(select auth.uid())); create policy "Admins manage business claims" on public.business_claims for all to authenticated using(public.is_admin()) with check(public.is_admin());